class BidirectionalMap {
  constructor(object = null) {
    this._map = new Map()
    this._reverse = new Map()
    if (object) {
      for (let attr in object) {
        if ({}.hasOwnProperty.call(object, attr)) {
          this.set(attr, object[attr])
        }
      }
    }
  }
  get size() {
    return this._map.size
  }
  set(key, value) {
    if (this._map.has(key)) {
      const _value = this._map.get(key)
      this._reverse.delete(_value)
    }
    if (this._reverse.has(value)) {
      const _key = this._reverse.get(value)
      this._map.delete(_key)
    }
    this._map.set(key, value)
    this._reverse.set(value, key)
    return this
  }
  get(key) {
    return this._map.get(key)
  }
  getKey(value) {
    return this._reverse.get(value)
  }
  clear() {
    this._map.clear()
    this._reverse.clear()
  }
  delete(key) {
    if (!this._map.has(key)) return false

    const value = this._map.get(key)
    this._map.delete(key)
    this._reverse.delete(value)
    return true
  }
  deleteValue(value) {
    if (!this._reverse.has(value)) return false

    const key = this._reverse.get(value)
    this._map.delete(key)
    this._reverse.delete(value)
    return true
  }
  entries() {
    return this._map.entries()
  }
  has(key) {
    return this._map.has(key)
  }
  hasValue(value) {
    return this._reverse.has(value)
  }
  keys() {
    return this._map.keys()
  }
  values() {
    return this._map.values()
  }
  getObject() {
    for (const key of this._map.keys()) {
      if (!isPrimitive(key)) {
        throw new Error('There are non-primitive keys')
      }
    }
    return Object.fromEntries(this._map.entries())
  }
  getObjectReverse() {
    for (const key of this._reverse.keys()) {
      if (!isPrimitive(key)) {
        throw new Error('There are non-primitive keys')
      }
    }
    return Object.fromEntries(this._reverse.entries())
  }
  [Symbol.iterator]() {
    return this.entries()
  }
}

function isPrimitive(value) {
  return value === null || !(typeof value === 'object' || typeof value === 'function')
}

module.exports = BidirectionalMap
